package com.oms.service;import com.oms.config.Db;import com.oms.dao.*;import com.oms.model.*;import java.math.BigDecimal;import java.sql.*;import java.util.*;
public class InventoryCountService{private final InventoryCountDao dao=new InventoryCountDao();private final AuditLogDao audit=new AuditLogDao();public InventoryCountDao.PageData page()throws SQLException{try(Connection c=Db.getConnection()){return dao.page(c);}}public long create(long warehouse,String note,User actor)throws SQLException{if(warehouse<=0)throw new ServiceException("Chọn kho kiểm kê.");requireScope(actor,warehouse);String clean=note==null?"":note.strip();return Db.inTransaction(c->{String code=String.format("KK%06d",dao.next(c));long id=dao.create(c,code,warehouse,clean,actor.getId());audit.log(c,actor.getId(),"INVENTORY_COUNT_CREATE","INVENTORY_COUNT",id,code);return id;});}public void count(long id,List<BigDecimal> actual,User actor)throws SQLException{Db.inTransaction(c->{var k=dao.lock(c,id);if(k==null||"POSTED".equals(k.status()))throw new ServiceException("Phiếu kiểm kê không còn được nhập số liệu.");requireScope(actor,k.warehouseId());if(actual.size()!=k.lines().size()||actual.stream().anyMatch(x->x==null||x.signum()<0))throw new ServiceException("Nhập đủ tồn thực tế không âm.");dao.saveActual(c,id,actual);audit.log(c,actor.getId(),"INVENTORY_COUNT_SAVE","INVENTORY_COUNT",id,k.code());return null;});}public void post(long id,User actor)throws SQLException{Db.inTransaction(c->{var k=dao.lock(c,id);if(k==null||!"COUNTED".equals(k.status()))throw new ServiceException("Phiếu phải được nhập đủ số thực tế trước khi chốt.");requireScope(actor,k.warehouseId());dao.post(c,k,actor.getId());audit.log(c,actor.getId(),"INVENTORY_COUNT_POST","INVENTORY_COUNT",id,k.code());return null;});}private static void requireScope(User actor,long warehouse){if(!actor.isAdmin()&&actor.getWarehouses().stream().map(NamedItem::getId).noneMatch(id->id==warehouse))throw new ForbiddenException("Bạn không phụ trách kho này.");}}
